import os, re, json

d = os.path.normpath(os.environ['RLM_SESSION_DIR'])
session_file = d+'/../../sessions/'+os.path.basename(d)+'.jsonl'

with open(session_file, 'r') as f:
    lines = f.readlines()

# Parse the JSON lines more carefully
for i, line in enumerate(lines):
    line = line.strip()
    if not line:
        continue
    try:
        msg = json.loads(line)
        if msg.get('type') == 'toolResult':
            tool_name = msg.get('toolCallId', '').rsplit('call_', 1)[-1]
            content = msg.get('content', '')
            # Check if there's any demo info
            if 'Demo' in content or 'grid' in content.lower():
                print(f"Line {i} ({tool_name}): {content[:300]}")
    except:
        pass
